(function() {
    'use strict';

    var nav = document.getElementById('nav');
    if (nav) {
      window.addEventListener('scroll', function() {
        nav.classList.toggle('scrolled', window.scrollY > 10);
      }, { passive: true });
    }

    var WEATHER_CITIES = [
      { name: 'לונדון', lat: 51.51, lon: -0.12 },
      { name: 'בודפשט', lat: 47.50, lon: 19.04 },
      { name: 'וינה', lat: 48.21, lon: 16.37 },
      { name: 'אתונה', lat: 37.98, lon: 23.73 },
      { name: 'פראג', lat: 50.08, lon: 14.44 },
      { name: 'ורשה', lat: 52.23, lon: 21.01 },
      { name: 'ברטיסלבה', lat: 48.15, lon: 17.11 },
      { name: 'ברצלונה', lat: 41.39, lon: 2.17 },
      { name: 'אמסטרדם', lat: 52.37, lon: 4.90 },
      { name: 'רומא', lat: 41.90, lon: 12.49 }
    ];
    var weatherCityIndex = Math.floor(Math.random() * WEATHER_CITIES.length);

    function fetchMenuWeather() {
      var el = (document.getElementById("__legacy_menuWeatherSnippet") || document.createElement("span"));
      if (!el) return;
      weatherCityIndex = (weatherCityIndex + 1) % WEATHER_CITIES.length;
      var city = WEATHER_CITIES[weatherCityIndex];
      el.textContent = city.name + '...';
      fetch('https://api.open-meteo.com/v1/forecast?latitude=' + city.lat + '&longitude=' + city.lon + '&current_weather=true')
        .then(function(r) { return r.json(); })
        .then(function(d) {
          var t = Math.round(d.current_weather.temperature);
          var code = d.current_weather.weathercode;
          var icon = code <= 1 ? '☀️' : code <= 3 ? '⛅' : code <= 67 ? '🌧' : '❄️';
          el.textContent = city.name + ' עכשיו ' + t + '°C ' + icon;
        })
        .catch(function() { el.textContent = 'מזג אוויר באירופה'; });
    }

    var hamburger = (document.getElementById("__legacy_hamburgerBtn") || document.createElement("button"));
    var mobileMenu = (document.getElementById("__legacy_mobileMenu") || document.createElement("div"));
    if (hamburger && mobileMenu) {
      hamburger.addEventListener('click', function(e) {
        e.stopPropagation();
        var isOpen = mobileMenu.classList.toggle('open');
        hamburger.setAttribute('aria-expanded', isOpen.toString());
        hamburger.setAttribute('aria-label', isOpen ? 'סגור תפריט' : 'פתח תפריט');
        document.body.style.overflow = isOpen ? 'hidden' : '';
        if (isOpen) fetchMenuWeather();
      });
      mobileMenu.querySelectorAll('a').forEach(function(link) {
        link.addEventListener('click', function() {
          mobileMenu.classList.remove('open');
          hamburger.setAttribute('aria-expanded', 'false');
          hamburger.setAttribute('aria-label', 'פתח תפריט');
          document.body.style.overflow = '';
        });
      });
      document.addEventListener('keydown', function(e) {
        if (e.key !== 'Escape') return;
        if (!mobileMenu.classList.contains('open')) return;
        mobileMenu.classList.remove('open');
        hamburger.setAttribute('aria-expanded', 'false');
        hamburger.setAttribute('aria-label', 'פתח תפריט');
        document.body.style.overflow = '';
        hamburger.focus();
      });
    }

    try {
      var _sub = new URLSearchParams(window.location.search).get('subscribed');
      if (_sub === '1') localStorage.setItem('mtEmailSubmitted', '1');
    } catch (e) {}

    var epOverlay = (document.getElementById("__legacy_emailPopupOverlay") || document.createElement("div"));
    var epClose = (document.getElementById("__legacy_emailPopupClose") || document.createElement("button"));
    var epForm = (document.getElementById("__legacy_emailPopupForm") || document.createElement("form"));
    var plausiblePage = 'slovakia-advanced';
    var epOpenedAt = 0;

    function closeEP() {
      if (!epOverlay) return;
      epOverlay.classList.remove('open');
      document.body.style.overflow = '';
    }
    function openEP(fromNav) {
      if (!epOverlay) return;
      if (epOverlay.classList.contains('open')) {
        if (!fromNav) return;
        epOpenedAt = Date.now();
        if (window.plausible) {
          plausible('Newsletter-Open-Nav', { props: { page: plausiblePage } });
        }
        return;
      }
      epOverlay.classList.add('open');
      document.body.style.overflow = 'hidden';
      epOpenedAt = Date.now();
      if (fromNav && window.plausible) {
        plausible('Newsletter-Open-Nav', { props: { page: plausiblePage } });
      }
    }
    window.openEmailPopup = function() { openEP(true); };
    if (epClose) epClose.addEventListener('click', closeEP);
    if (epOverlay) epOverlay.addEventListener('click', function(e) {
      if (e.target === epOverlay && Date.now() - epOpenedAt > 400) closeEP();
    });
    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape') closeEP();
    });

    function closeMobileMenuForNewsletter() {
      var mm = (document.getElementById("__legacy_mobileMenu") || document.createElement("div"));
      var hb = (document.getElementById("__legacy_hamburgerBtn") || document.createElement("button"));
      if (mm && mm.classList.contains('open')) {
        mm.classList.remove('open');
        if (hb) {
          hb.setAttribute('aria-expanded', 'false');
          hb.setAttribute('aria-label', 'פתח תפריט');
        }
        document.body.style.overflow = '';
      }
    }
    document.addEventListener('click', function(e) {
      var link = e.target.closest('a[href="#newsletter"], a[href="tips.html#newsletter"]');
      if (!link) return;
      e.preventDefault();
      closeMobileMenuForNewsletter();
      openEP(true);
    }, true);

    if (epForm) epForm.addEventListener('submit', function() {
      try { localStorage.setItem('mtEmailSubmitted', '1'); } catch (e) {}
    });

    var scrollTopBtn = document.getElementById('scrollTopBtn');
    function updateScrollTopBtn() {
      if (!scrollTopBtn) return;
      var show = window.scrollY > 180;
      scrollTopBtn.classList.toggle('is-visible', show);
      scrollTopBtn.setAttribute('aria-hidden', show ? 'false' : 'true');
      scrollTopBtn.setAttribute('tabindex', show ? '0' : '-1');
    }
    window.addEventListener('scroll', updateScrollTopBtn, { passive: true });
    updateScrollTopBtn();
    if (scrollTopBtn) {
      scrollTopBtn.addEventListener('click', function() {
        try {
          window.scrollTo({ top: 0, behavior: 'smooth' });
        } catch (e) {
          window.scrollTo(0, 0);
        }
      });
    }
  })();

