(function () {
    var btn = document.getElementById('promoCopyMatay6');
    var label = btn && btn.querySelector('.article-partner-callout__copy-label');
    var live = document.getElementById('promoCopyMatay6Live');
    if (!btn || !label) return;

    var CODE = (btn.getAttribute('data-code') || 'MATAY6').trim();
    var COPIED_MS = 2200;
    var resetTimer;

    function fallbackCopy(text) {
      var ta = document.createElement('textarea');
      ta.value = text;
      ta.setAttribute('readonly', '');
      ta.setAttribute('aria-hidden', 'true');
      ta.style.cssText = 'position:fixed;left:-9999px;top:0';
      document.body.appendChild(ta);
      ta.select();
      try {
        return document.execCommand('copy');
      } catch (err) {
        return false;
      } finally {
        document.body.removeChild(ta);
      }
    }

    function copyToClipboard(text) {
      if (navigator.clipboard && typeof navigator.clipboard.writeText === 'function') {
        return navigator.clipboard.writeText(text).then(function () { return true; }).catch(function () {
          return fallbackCopy(text);
        });
      }
      return Promise.resolve(fallbackCopy(text));
    }

    function showCopied() {
      clearTimeout(resetTimer);
      label.textContent = 'הועתק';
      label.removeAttribute('translate');
      btn.classList.add('is-copied');
      btn.setAttribute('aria-label', 'הועתק ללוח העתקה');
      if (live) live.textContent = 'הועתק ללוח העתקה';
      resetTimer = setTimeout(function () {
        label.textContent = CODE;
        label.setAttribute('translate', 'no');
        btn.classList.remove('is-copied');
        btn.setAttribute('aria-label', 'העתקת קוד הקופון MATAY6 ללוח העתקה');
        if (live) live.textContent = '';
      }, COPIED_MS);
    }

    function showCopyFailed() {
      if (live) live.textContent = 'לא הצלחנו להעתיק אוטומטית - אפשר לסמן את הקוד ולהעתיק ידנית';
      setTimeout(function () {
        if (live) live.textContent = '';
      }, 5000);
    }

    btn.addEventListener('click', function () {
      copyToClipboard(CODE).then(function (ok) {
        if (ok) {
          showCopied();
          if (window.plausible) {
            try {
              plausible('PartnerCarRental-CodeCopy', { props: { partner: 'barkro', code: CODE, source: 'slovakia-advanced-article' } });
            } catch (ex) {}
          }
        } else {
          showCopyFailed();
        }
      });
    });
  })();
